INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120007, 'spa', 'El sentido dominante del Qal activo', 'El sentido dominante del Qal activo: derribar, demoler o destruir una estructura. Abarca altares (Éx 34:13; Jue 6:30), casas (Lv 14:45), muros (2 Re 25:10; Jer 52:14), lugares altos (2 Re 23:7-15) y fortificaciones urbanas (Jue 8:9; 9:45). Es el verbo estándar de mandato en la purificación cultual — ''derribaréis sus altares.'' La fuerza de tracción hacia abajo reside en el núcleo del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120008, 'spa', 'Piel intensivo', 'Piel intensivo: demoler a fondo, con énfasis en la completitud o destrucción sistemática. Se encuentra 7 veces, concentrado en las narrativas de reforma de Crónicas — la purga de Ezequías (2 Cr 31:1), Manasés reconstruyendo lo que había destruido (2 Cr 33:3) y la campaña exhaustiva de Josías (2 Cr 34:4, 7). La conjugación Piel añade minuciosidad intencional a la demolición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120015, 'spa', 'Extensión metafórica a destrozar dientes o huesos en lugar de estructuras constr', 'Extensión metafórica a destrozar dientes o huesos en lugar de estructuras construidas. En el Salmo 58:6 el salmista ora ''arranca los colmillos de los leoncillos, oh SEÑOR'' — el verbo de demolición se aplica al cuerpo. Nahúm 1:6 pregunta ''¿quién resistirá ante su indignación?'' con las rocas despedazadas por su furia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120016, 'spa', 'Formas de voz pasiva (Nifal, Pual, Qal pasivo)', 'Formas de voz pasiva (Nifal, Pual, Qal pasivo): ser derribado, ser demolido. Se encuentra en 4 ocurrencias que describen estructuras que han sufrido o sufrirán demolición. Levítico 11:35 ordena que los hornos contaminados ''serán derribados''; Jueces 6:28 informa que el altar de Baal ''fue derribado''; Jeremías 4:26 contempla ciudades ''derribadas'' ante la ira ardiente del SEÑOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120020, 'spa', 'Demolición metafórica de una persona', 'Demolición metafórica de una persona: Dios ''me derriba por todos lados'' (Job 19:10). Aquí נָתַץ describe no la demolición estructural sino el desmantelamiento sistemático de una vida humana — Job experimenta la acción de Dios como el desgarramiento de todo lo que sostenía su existencia. La violencia arquitectónica del verbo se redirige hacia dentro, haciendo que el sufriente se sienta como un edificio siendo arrasado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120037, 'spa', 'Piel intensivo activo', 'Piel intensivo activo: romper, quebrar o desgarrar por la fuerza ligaduras, cuerdas o cadenas. Es el sentido más vívido, con 9 ocurrencias concentradas en escenas de liberación de ataduras. Sansón rompe cuerdas nuevas (Jue 16:9, 12), el salmista imagina a las naciones quebrando los lazos de Dios (Sal 2:3), y el pueblo de Dios es liberado de las cadenas de maldad (Is 58:6; Sal 107:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120038, 'spa', 'Piel con matiz de arrancar o extraer de raíz, aplicado a estacas de tienda y pla', 'Piel con matiz de arrancar o extraer de raíz, aplicado a estacas de tienda y plantas. Ezequiel 17:9 pregunta si las raíces de una vid trasplantada serán ''arrancadas'', y Ezequiel 23:34 emplea la imagen de desgarrarse los propios pechos en duelo. Solo 2 ocurrencias, pero la clase de objeto (cosas enraizadas, que crecen) distingue este sentido del mero romper ataduras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120041, 'spa', 'Nifal pasivo de quebrar', 'Nifal pasivo de quebrar: ser roto, ser quebrado, dicho de cuerdas, sogas o ataduras que ceden bajo la tensión. Seis ocurrencias describen el resultado y no el acto — las cuerdas de arco de Sansón ''fueron rotas'' como lino quemado (Jue 16:9), los propósitos de Job ''se quiebran'' (Job 17:11) y la cuerda triple de Eclesiastés 4:12 ''no se rompe fácilmente''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120044, 'spa', 'Sentidos Qal e Hifil de alejar o atraer fuera de una posición a personas', 'Sentidos Qal e Hifil de alejar o atraer fuera de una posición a personas. Este uso militar y político aparece 5 veces: Josué atrae a los hombres de Hai fuera de la ciudad (Jos 8:6), guerreros israelitas atraen a los benjaminitas a la persecución (Jue 20:32), y Dios amenaza con ''arrancar'' a Joaquín como un anillo de sello de su dedo (Jer 22:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120047, 'spa', 'Hofal y Nifal pasivo de ser atraído fuera o apartado, imagen especular del senti', 'Hofal y Nifal pasivo de ser atraído fuera o apartado, imagen especular del sentido 3. Josué 8:16 y Jueces 20:31 describen defensores que ''fueron atraídos'' fuera de su ciudad por una retirada fingida. La perspectiva pasiva enfatiza que los soldados no eligieron salir sino que fueron engañados para hacerlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120050, 'spa', 'Nifal pasivo de desarraigar', 'Nifal pasivo de desarraigar: ser arrancado, desarraigado o separado de un lugar fijo. Tres ocurrencias describen el desalojo permanente — los pies de los sacerdotes son ''levantados'' del Jordán al volver las aguas (Jos 4:18), el impío es ''arrancado de su tienda'' (Job 18:14) y el plomo no logra ''separarse'' de la escoria (Jer 6:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120063, 'spa', 'tiña, erupción cutánea', 'Una tiña o erupción cutánea que afecta la cabeza o la barba, que requiere examen sacerdotal dentro del sistema de pureza levítico. Las catorce apariciones se encuentran en Levítico 13:30–37 y el resumen en 14:54. El sacerdote inspecciona pelo fino amarillento, profundidad bajo la superficie de la piel y si la afección se ha extendido durante dos períodos sucesivos de aislamiento de siete días.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120065, 'spa', 'Saltar o estremecer', 'Levítico usa el infinitivo Piel para el salto característico de las langostas, el movimiento que distingue a los insectos permitidos. Job emplea el Qal imperfecto para el brinco involuntario del corazón ante el trueno de Dios. El Hifil causativo de Habacuc muestra a Dios haciendo ''sobresaltarse'' a las naciones en terror, un estremecimiento forzado ante la gloria divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120066, 'spa', 'Desatar o soltar ataduras', 'Desatar o aflojar restricciones físicas como correas, yugos o ligaduras de maldad. Isaías 58:6 ordena soltar las correas del yugo como parte del verdadero ayuno. El énfasis recae en las ataduras materiales más que en la persona atada. El Salmo 105:20 lo emplea para la liberación de José de sus cadenas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120069, 'spa', 'Arrancar, desarraigar — Arrancar o sacar de raíz en construcciones Qal activas, ', 'Arrancar, desarraigar — Arrancar o sacar de raíz en construcciones Qal activas, incluyendo imperativos, infinitivos y participios. Aplicado literalmente a arrancar las aseras (Miq 5:13) y figuradamente a naciones y reinos arrancados de su tierra. Jeremías lo usa programáticamente: Dios designa al profeta ''para arrancar y derribar, para edificar y plantar'' (Jer 1:10). El español ''arrancar'' y el francés ''arracher'' preservan la misma imagen de extracción desde la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120077, 'spa', 'Ser desarraigado, ser arrancado — El sentido pasivo o estativo expresado mediant', 'Ser desarraigado, ser arrancado — El sentido pasivo o estativo expresado mediante los troncos Nifal y Hofal, describiendo el ser desarraigado o arrancado de su lugar. Con frecuencia denota la consecuencia irreversible del juicio divino sobre naciones o ciudades (Ez 19:12; Dn 11:4), aunque Amós 9:15 promete que Israel ''nunca más será arrancado'' — la reversión definitiva. Este sentido enfatiza el estado resultante de la destrucción más que la acción misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120086, 'spa', 'Sea (medida de áridos)', 'Una sea, medida específica de volumen seco equivalente a aproximadamente un tercio de efa (unos 7,3 litros), usada para medir harina, grano y semilla. Pasajes clave incluyen la ofrenda de hospitalidad de Abraham de tres seas (Gn 18:6), el regalo de Abigail de cinco seas (1 S 25:18), la medida de la zanja del altar de Elías (1 R 18:32) y la profecía de Eliseo sobre restauración económica medida por sea (2 R 7:1, 16, 18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120096, 'spa', 'Embriaguez excesiva', 'Denota el consumo excesivo de bebida o el estado de embriaguez. Las formas participiales (סֹבֵא, סֹבְאֵי) funcionan como sustantivos que significan «borracho» o «bebedor», y aparecen en advertencias éticas en Proverbios y Deuteronomio. El cohortativo de Isaías 56:12 expresa abandono deliberado al vicio, mientras que Nahúm 1:10 alude a malhechores consumidos por su propia borrachera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120098, 'spa', 'Nombre propio geográfico', 'Nombre personal y geográfico que designa tanto a un hijo de Cus como a una nación o territorio del sur. La Tabla de las Naciones (Génesis 10:7 // 1 Crónicas 1:9) establece a Seba como primogénito de Cus, mientras que los textos proféticos y poéticos (Salmo 72:10, Isaías 43:3) lo presentan como una nación rica que ofrece tributo o queda sujeta al juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120099, 'spa', 'Bebida embriagante', 'Denota una bebida fuerte, licor o el estado de embriaguez. Isaías 1:22 lo usa metafóricamente para la justicia corrompida. Las referencias de Oseas 4:18 y Nahúm 1:10 son textualmente difíciles, con interpretaciones que van desde «su bebida» hasta «borracho» o lecturas enmendadas. Las glosas multilingües reflejan esta ambigüedad entre el sentido de bebida y el de persona ebria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120101, 'spa', 'volverse, cambiar dirección', 'Giro intransitivo del sujeto: la persona o cosa se vuelve, retrocede o cambia de orientación. Gn 42:24 (José se apartó de ellos), Dt 2:3 (ya habéis rodeado bastante este monte, volveos al norte), 1 S 15:12, 27 (Saúl se apartó) muestran cambio de dirección sin objeto directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120102, 'spa', 'rodear, circundar', 'Cercar o rodear a una persona, lugar u objeto, ya sea con intención hostil (asedio) o protectora. Gn 2:11, 13 (ríos que rodean tierras), Gn 37:7 (gavillas que rodean la de José), Jue 16:2, 20:5 (rodear una casa o ciudad para atacar) ilustran el uso transitivo con objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120103, 'spa', 'torcerse, serpentear', 'Giro reflexivo o de voz media: un lindero serpentea, una frontera cambia de rumbo, algo gira por sí mismo sin agente externo. Nm 34:4-5, Jos 15:3 (el lindero girará y pasará) describen límites geográficos que cambian de dirección. Gn 19:4 muestra un uso similar de cerco espontáneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120107, 'spa', 'hacer girar, desviar', 'Causativo: hacer girar algo o a alguien, cambiar la dirección, desviar o redirigir, incluyendo rostros, corazones o grupos. Jue 18:23 (volvieron sus rostros), 1 R 8:14, 18:37 (volver sus corazones) muestran al agente provocando un cambio de dirección o estado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120108, 'spa', 'recorrer, dar vuelta', 'Viajar alrededor, hacer un circuito, patrullar o marchar en torno, con énfasis en la trayectoria recorrida más que en el rodeo estático. Nm 21:4 (rodeando Edom), Jos 6:3 (marchar alrededor de la ciudad), Ec 2:20 (me volví a la desesperanza en todo mi trabajo) muestran movimiento a lo largo de un circuito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120112, 'spa', 'rodear intensivamente', 'Circunvalación intensificada o repetida, a menudo en contextos ceremoniales o enfáticos. Dt 32:10 (lo rodeó, lo cuidó), Sal 7:7, 26:6, 32:7, 10 (rodéame de liberación, rodeo tu altar) exhiben la fuerza iterativa o intensiva del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120114, 'spa', 'trasladar, hacer pasar', 'Movimiento causativo de objetos o personas de un lugar a otro: llevar alrededor, conducir, retirar o reubicar. Éx 13:18 (Dios hizo rodear al pueblo por el desierto), 1 S 5:8-10 (que trasladen el arca a Gat, a Ecrón) muestran reubicación espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120129, 'spa', 'cambiar, transformar', 'Acepción intransitiva poco frecuente que extiende el giro físico a la transformación metafórica o cambio de estado. 1 S 22:22 (yo he causado la muerte de toda la casa de tu padre) y Zac 14:10 (la tierra se transformará en llanura) muestran cambio de condición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120148, 'spa', 'ser cambiado, ser vuelto', 'Pasivo del causativo: ser girado por un agente externo, ser cambiado o transformado pasivamente. Nm 32:38 (nombres que fueron cambiados) e Is 28:27 (el trillo no se hace girar sobre el comino) muestran el Hofal pasivo. Es la conjugación menos frecuente de este verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120216, 'spa', 'alrededor, en derredor', 'Uso adverbial y preposicional ''alrededor, en derredor, por todos lados'' (319 veces): la acepción espacial dominante que indica cerco o posición circundante. Aparece con preposiciones (מִסָּבִיב ''desde alrededor'', עַל־סָבִיב ''sobre el circuito'') y sufijos pronominales. Gn 23:17 lo emplea para los linderos del campo de Abraham; las visiones del templo en Ezequiel lo saturan para medidas arquitectónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120225, 'spa', 'alrededores, los circundantes', 'Uso sustantival (17 veces) donde סָבִיב funciona como nombre: ''los alrededores, el entorno, los pueblos o lugares vecinos''. A menudo con artículo o en estado constructo: הַסָּבִיב ''el circuito'' (1 Cr 11:8), o con formas sufijadas significando ''los que están a su alrededor''. Sal 76:11 llama a ''todos los que están a su alrededor'' (סְבִיבָיו) a traer ofrendas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120253, 'spa', 'giros cíclicos perpetuos', 'Ocurrencia singular en Eclesiastés 1:6 que describe el curso circular del viento: va al sur, gira al norte, ''girando y girando va el viento'' (סָבִיב סָבִיב). La duplicación intensifica el sentido de movimiento cíclico perpetuo. Algunas traducciones lo tratan como nominal (''sus giros''), reflejando un uso filosófico-cosmológico único en la Biblia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120265, 'spa', 'Espesura vegetal', 'Denota un matorral denso o vegetación enmarañada, generalmente en zonas boscosas. Génesis 22:13 ofrece la referencia más memorable: el carnero atrapado en la espesura del monte Moria. Isaías 9:18 y 10:34 lo emplean en oráculos de juicio donde el fuego consume o el hacha derriba las espesuras del bosque. El Salmo 74:5, de texto difícil, también podría aludir a matorrales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120266, 'spa', 'Instrumento musical', 'Instrumento musical de la orquesta de Nabucodonosor, mencionado cuatro veces en Daniel 3:5, 7, 10, 15. Su identificación precisa es incierta, pero el cognado griego σαμβύκη sugiere una lira o arpa triangular. Las traducciones varían: «trigón» (término técnico), «lira» en español. El instrumento formaba parte del conjunto que acompañaba la adoración de la estatua de oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120267, 'spa', 'Nombre propio', 'Nombre personal que designa a uno de los valientes guerreros y comandantes militares de David. Sibecai el husatita aparece en los relatos de batalla (2 Samuel 21:18, 1 Crónicas 20:4), en la lista de los Treinta (1 Crónicas 11:29) y como líder de la octava división mensual (1 Crónicas 27:11). Las versiones griegas presentan variantes como Σοβοχαι.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120268, 'spa', 'Cargar, llevar', 'Significado básico del Qal: cargar, llevar o sostener un peso, ya sea literal (Isacar inclinándose para cargar, Gn 49:15; portando un ídolo, Is 46:7) o teológico (el Siervo cargando el dolor y la culpa, Is 53:4, 11). Lamentaciones 5:7 extiende el sentido a cargar con las iniquidades de los antepasados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120273, 'spa', 'Estar cargado', 'Participio pasivo Pual: estar cargado o abarrotado, describiendo ganado u bueyes colmados de carga o productos (Sal 144:14). Algunos intérpretes leen ''preñado'', pero la evidencia multilingüe favorece la imagen de bestias abrumadas por el peso de los bienes, retrato de abundancia y bendición agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120274, 'spa', 'Arrastrarse penosamente', 'Hitpael reflexivo: arrastrarse con dificultad, usado únicamente en la alegoría del envejecimiento en Eclesiastés 12:5, donde hasta el saltamontes se vuelve una carga. Esta forma reflexiva enfatiza que el sujeto es a la vez portador y carga, una imagen singularmente expresiva del deterioro corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120277, 'spa', 'Carga y servidumbre', 'El programa de trabajo forzado de Salomón (1 Reyes 11:28) ejemplifica la opresión institucional, la carga que provocó la rebelión de Israel. Los obreros de Nehemías (4:17) sufren agotamiento físico por cargar materiales durante la reconstrucción. El Salmo 81:6 usa ''carga'' metafóricamente para el peso de la esclavitud, que Dios quitó en el Éxodo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120278, 'spa', 'Opresión tiránica', 'Las tres apariciones pertenecen a los oráculos de liberación de Isaías contra la dominación asiria. El término siempre se asocia con imágenes de hombros y yugos, el peso físico que aplasta a un pueblo sometido. La referencia de Isaías 9:4 a Madián evoca la victoria milagrosa de Gedeón. La frase repetida ''su carga se apartará'' (10:27; 14:25) crea un estribillo de libertad prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120279, 'spa', 'Cargador de construcción', 'Cargador u obrero de acarreo empleado en construcciones a gran escala, usado colectivamente para cuadrillas de trabajo forzado. La fuerza laboral del Templo de Salomón incluía 70.000 de estos junto a 80.000 canteros (2 Cr 2:2). En Nehemías 4:10, su fuerza debilitada señala la desmoralización del pueblo durante la reconstrucción de la muralla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120280, 'spa', 'Carga, trabajo forzado', 'Las cargas pesadas y el sistema de trabajo forzado padecidos por Israel en Egipto, abarcando tanto las cargas físicas como la servidumbre obligatoria. Las seis ocurrencias se concentran en Éxodo 1-6, creando un arco temático: las cargas son impuestas (1:11), presenciadas por Moisés (2:11), motivo de queja de Faraón cuando se interrumpen (5:4-5), y finalmente Dios promete levantarlas (6:6-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120290, 'spa', 'Postrarse en adoración', 'Postrarse en adoración ante un ídolo, usado exclusivamente en Isaías 44-46 como parte de la polémica profética contra la idolatría. Isaías emplea esta palabra con aguda ironía: un hombre corta un árbol, usa la mitad como combustible, y ante la otra mitad «se postra» (Is 44:15,17,19). Isaías 46:6 extiende esto a los ídolos de oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120296, 'spa', 'Adorar, postrarse', 'Postrarse en adoración o rendir homenaje, usado exclusivamente en el arameo de Daniel para la veneración religiosa. El contexto principal es la adoración obligatoria de la estatua de oro de Nabucodonosor (Dn 3:5-7, 10-12, 14-15, 18, 28), emparejado con נְפַל («caer»). También para el homenaje de Nabucodonosor a Daniel (Dn 2:46). Cognado del árabe sajada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120305, 'spa', 'Posesión atesorada', 'Una posesión valiosa, escogida personalmente, o un tesoro. En su uso teológico, expresa la elección pactual de Dios sobre Israel como su pueblo preciado, distinto de todas las naciones (Éx 19:5, «seréis mi סְגֻלָּה de entre todos los pueblos»; Dt 7:6; 14:2; 26:18; Mal 3:17; Sal 135:4). En contextos reales y sapienciales designa el tesoro personal de objetos preciosos de un rey (1 Cr 29:3; Ecl 2:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120312, 'spa', 'Funcionario imperial provincial', 'Alto funcionario administrativo en la jerarquía gubernamental babilónico-persa, mencionado sistemáticamente junto a otros oficiales imperiales en enumeraciones formales de la corte. Daniel es elevado por encima de estos funcionarios (Dn 2:48), y aparecen como clase en las asambleas de Nabucodonosor (Dn 3:2-3). El término es un préstamo del asirio que refleja rangos burocráticos mesopotámicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120313, 'spa', 'Prefecto, funcionario, gobernante', 'Prefecto, funcionario, gobernante: oficial designado en una burocracia provincial, derivado del acadio šaknu (''el puesto en su lugar''). En textos proféticos como Ezequiel 23:6, 12 y Jeremías 51:23, 57, designa a altos administradores de los imperios asirio y babilónico, emparejado constantemente con פַּחוֹת. En Nehemías (2:16; 4:14; 5:7; 12:40; 13:11) se aplica a líderes cívicos judíos que supervisaron la reconstrucción y las reformas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120321, 'spa', 'Puro, refinado (participio pasivo Qal) — participio pasivo especializado aplicad', 'Puro, refinado (participio pasivo Qal) — participio pasivo especializado aplicado casi exclusivamente al oro: refinado, puro, fundido y sellado. El hebreo extiende la metáfora del cierre a la purificación metalúrgica. Casi todas las ocurrencias se concentran en las descripciones del templo de Salomón (1 R 6-7, 10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120322, 'spa', 'Cerrar, clausurar (Qal) — el significado fundacional', 'Cerrar, clausurar (Qal) — el significado fundacional: cerrar físicamente una puerta, portón o abertura. Pasajes clave incluyen a Dios cerrando el arca detrás de Noé (Gn 7:16) y cerrando la carne de Adán (Gn 2:21). Las 36 ocurrencias abarcan desde cierres cotidianos hasta actos teológicamente significativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120323, 'spa', 'Poner en cuarentena, aislar (Hifil causativo) — el confinamiento causativo espec', 'Poner en cuarentena, aislar (Hifil causativo) — el confinamiento causativo específico de la cuarentena o aislamiento durante la inspección levítica de enfermedades cutáneas (Lv 13-14). El sacerdote ''encierra'' a la persona afectada durante siete días de observación, constituyendo un dominio conceptual distinto del mero cerrar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120329, 'spa', 'Entregar, poner en manos de (Hifil/Piel) — entregar o rendir a una persona ante ', 'Entregar, poner en manos de (Hifil/Piel) — entregar o rendir a una persona ante un enemigo o autoridad. Deuteronomio 23:15 prohíbe entregar al esclavo fugitivo, y 1 Samuel 23:11 registra la angustia de David ante la posibilidad de ser entregado por los hombres de Keila. Una extensión semántica genuina respecto de ''cerrar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120330, 'spa', 'Estar cerrado, ser clausurado (Nifal) — pasivo o reflexivo', 'Estar cerrado, ser clausurado (Nifal) — pasivo o reflexivo: estar cerrado, confinado. Se usa de Miriam encerrada fuera del campamento (Nm 12:14-15), de las puertas de la ciudad atrancadas al anochecer (Neh 13:19) y del cierre figurativo de puertas ante Ciro (Is 45:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120336, 'spa', 'Confinar, encarcelar (Piel intensivo) — encerrar, confinar o aprisionar a una pe', 'Confinar, encarcelar (Piel intensivo) — encerrar, confinar o aprisionar a una persona con acción deliberada y enérgica. Destaca en el reconocimiento de David de que Dios ''encerró'' a Saúl en su mano (1 S 24:18) y en el encarcelamiento escatológico de Isaías 24:22.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120345, 'spa', 'Estar firmemente cerrado, atrancado (Pual pasivo) — pasivo intensivo que implica', 'Estar firmemente cerrado, atrancado (Pual pasivo) — pasivo intensivo que implica una clausura más completa que el simple Nifal. Jericó estaba ''completamente cerrada'' (Jos 6:1), y la ciudad apocalíptica tiene cada casa atrancada (Is 24:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120381, 'spa', 'Vestidura de lino', 'Prenda fina de lino, posiblemente una túnica, manto o lienzo rectangular. En Jueces 14, Sansón la empareja con «mudas de vestidos» (חֲלִפֹת בְּגָדִים) en su apuesta, lo que sugiere un artículo de vestir valioso. Proverbios 31:24 la presenta como producto comercial de mano de obra hábil. Isaías 3:23 la enumera entre los lujos de las mujeres de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120382, 'spa', 'El nombre propio Sodoma, usado tanto como referente histórico de la ciudad destr', 'El nombre propio Sodoma, usado tanto como referente histórico de la ciudad destruida (Gn 10:19; 13:10-13; 14:2-22; 18-19) como tipo profético-proverbial de maldad extrema y catástrofe divina (Is 1:9-10; 13:19; Jer 23:14; Dt 29:22; Sof 2:9). Su destrucción por fuego y azufre (Gn 19:24-25) se convirtió en el paradigma supremo de Israel para el juicio divino contra el pecado. Los profetas la invocan como vara de medir: Isaías compara a los líderes de Jerusalén con ''gobernantes de Sodoma'' (Is 1:10) y Lamentaciones declara el castigo de Judá peor que el de Sodoma (Lam 4:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120388, 'spa', 'Prisión, cárcel', 'La prisión o casa redonda donde José fue confinado en Egipto, usada únicamente en la expresión compuesta בֵּית הַסֹּהַר (''casa del סֹהַר''). Las ocho ocurrencias se agrupan en Génesis 39:20-40:5, describiendo el lugar donde Potifar encerró a José, donde YHWH le mostró su fidelidad, y donde el jefe de los coperos y el jefe de los panaderos fueron recluidos junto a él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120390, 'spa', 'retroceder, retirarse', 'Retroceder, retirarse o ser rechazado, principalmente en sentido militar o físico. El salmista ora repetidamente para que los enemigos sean ''vueltos atrás'' o ''rechazados'' con vergüenza (Sal 35:4; 40:14; 70:2; 129:5). En el Salmo 44:18 la comunidad lamenta que ''nuestro corazón no retrocedió'' aun en la derrota, mientras Isaías 50:5 afirma ''no me volví atrás'' en firmeza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120391, 'spa', 'apostatar, apartarse de Dios', 'Apostatar o retroceder espiritualmente — apartarse de la lealtad a Dios, con una fuerte connotación moral y pactual. Proverbios 14:14 acuña la frase participial sug lev, ''el apóstata de corazón'', como tipo de carácter. El Salmo 80:18 contiene la apasionada promesa ''no nos apartaremos de ti'', y Sofonías 1:6 denuncia a ''los que se apartaron de seguir al SEÑOR''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120401, 'spa', 'desviarse, extraviarse', 'Desviarse o extraviarse, enfatizando la desviación del camino recto más que la retirada de una posición o la apostasía de un pacto. En el Salmo 53:3 (paralelo en Sal 14:3) ''todos se desviaron'' describe el extravío moral colectivo de la humanidad. La forma Qal aquí es notable — más simple y menos reflexiva que el Nifal — sugiriendo una deriva pasiva más que una rebelión activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120404, 'spa', 'Secreto, asunto confidencial', 'Secreto, asunto confidencial: materia confidencial o secreto confiado a alguien de confianza. Proverbios 11:13 advierte que el chismoso revela el סוֹד, y 20:19 repite la advertencia. Amós 3:7 declara que Dios no hace nada sin revelar su סוֹד a los profetas. El énfasis recae en el contenido de la confidencia, no en la reunión misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120405, 'spa', 'Concilio, asamblea', 'Concilio, asamblea: reunión deliberativa, un círculo de personas que se sientan juntas para discutir o decidir. Jeremías 6:11 habla de un סוֹד de jóvenes, Salmo 89:7 del concilio de santos (ángeles), y Salmo 111:1 lo empareja con עֵדָה (congregación). La cadena constructa especifica de quién es la asamblea: el consejo íntimo de Dios (Job 15:8), los rectos (Sal 111:1) o los impíos (Gn 49:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120406, 'spa', 'Comunión íntima, amistad', 'Comunión íntima, amistad: la calidez relacional de quienes comparten confidencias. Job 19:19 lamenta la pérdida de los ''hombres de mi סוֹד,'' y Job 29:4 recuerda los días cuando el סוֹד de Dios cubría su tienda. Salmo 55:14 lo usa para describir la dulce compañía entre antiguos amigos. Se trata del vínculo personal más que de la mera información.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120408, 'spa', 'Complot secreto, conspiración', 'Complot secreto, conspiración: un plan secreto tramado contra alguien. Salmo 64:2 pide a Dios refugio del סוֹד de los malvados, y Salmo 83:3 acusa a las naciones de urdir un סוֹד contra el pueblo de Dios. La palabra retiene su idea central de deliberación cerrada pero adquiere un tono marcadamente malicioso; el secreto se convierte en arma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120427, 'spa', 'Ungir, frotar con aceite', 'Ungirse o untar a otro con aceite, generalmente como parte del aseo personal o como marcador cultural de bienestar frente al duelo. La acción es reflexiva en la mayoría de las ocurrencias: Rut se unge para su encuentro con Booz (Rt 3:3), David se unge al terminar el duelo (2 S 12:20) y Daniel se abstiene de ungirse durante su ayuno (Dn 10:3). Deuteronomio 28:40 y Miqueas 6:15 lo presentan como bendición denegada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120436, 'spa', 'Instrumento de viento', 'Instrumento de viento, probablemente una gaita o flauta doble, parte del conjunto musical real en Daniel 3. El término aparece cuatro veces (Dan 3:5, 10, 10, 15) con variantes textuales entre ketiv y qeré. El préstamo del griego συμφωνία evidencia la influencia helenística en la corte babilónica y su cultura musical cosmopolita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120440, 'spa', 'caballo (el animal)', 'El caballo doméstico como animal, de manera abrumadora en contextos militares y reales: tiros de carro (Jue 5:22), monturas de caballería (2 R 2:11), mercancías comerciales (Gn 47:17) y símbolo profético del poder terrenal opuesto a la confianza divina (Is 31:1; Mi 5:9). Las 138 ocurrencias comparten este referente zoológico central, sin ambigüedad semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120472, 'spa', 'marca textual anómala', 'Ocurrencia singular y anómala en Neh 7:68, donde el texto masorético parece contener una marca de sección o una interrupción textual en lugar de un uso genuino de ''caballo''. La mayoría de las ediciones críticas modernas tratan esto como un artefacto escribal y no como una acepción léxica distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120477, 'spa', 'Perecer, ser arrebatado', 'Formas Qal que significan ''llegar a su fin, cesar, perecer, ser arrebatado''. El Salmo 73:19 muestra a los impíos arrebatados por terrores, Amós 3:15 declara que las casas de marfil llegarán a su fin, e Ester 9:28 afirma que la memoria de Purim no cesará. Abarca desde la destrucción violenta hasta el cese gradual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120480, 'spa', 'Consumir, destruir activamente', 'Formas causativas Hifil que significan ''acabar con, consumir, barrer'' como acto de juicio divino. En Sofonías 1:2 Dios anuncia «destruiré por completo todo de la faz de la tierra», y en Jeremías 8:13 «los recogeré y consumiré». Estas formas expresan la fuerza activa y judicial del tronco causativo, distinguiéndose del Qal pasivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120484, 'spa', 'Juncos o cañas en el compuesto geográfico Yam Suph, el ''Mar de los Juncos'', uso ', 'Juncos o cañas en el compuesto geográfico Yam Suph, el ''Mar de los Juncos'', uso dominante a lo largo del Pentateuco, los libros históricos y los Salmos. Desde el cruce del Mar Rojo (Éx 13:18; 15:4) hasta la flota de Salomón en sus costas (1 R 9:26) y los salmistas que rememoran la liberación (Sal 106:7, 9, 22), este sentido es geográfico y conmemorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120488, 'spa', 'Vegetación acuática real que crece a orillas de los ríos, como cuando la madre d', 'Vegetación acuática real que crece a orillas de los ríos, como cuando la madre de Moisés colocó la cesta ''entre los juncos'' (basuph, Éx 2:3, 5) y Miriam vigilaba cerca. Isaías 19:6 empareja suph con qaneh (caña), describiendo los canales de Egipto secándose. El español ''junco'' capta bien este sentido botánico literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120491, 'spa', 'Alga o materia vegetal submarina, usado únicamente en Jonás 2', 'Alga o materia vegetal submarina, usado únicamente en Jonás 2:5, donde el profeta que se ahogaba describe el suph enrollado alrededor de su cabeza en las profundidades. Cognados árabes apoyan esta extensión de los juncos de agua dulce a la vegetación marina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120493, 'spa', 'fin, conclusión', 'El punto terminal, la conclusión o el extremo final de algo, ya sea un lugar físico (final de un valle, 2 Cr 20:16), un fenómeno natural (retaguardia de una plaga de langostas, Jl 2:20) o un asunto abstracto (conclusión de toda enseñanza, Ecl 12:13). Eclesiastés 3:11 lo emplea teológicamente: la obra de Dios se extiende de principio a סוֹף sin que el hombre pueda abarcarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120494, 'spa', 'fin, extremo', 'El punto terminal o conclusión de algo en el uso arameo, que abarca extensión espacial (un árbol que llega hasta el confín de la tierra, Dn 4:11, 22), duración temporal (''hasta el fin'' significando para siempre, Dn 6:26, o una terminación fijada, Dn 7:26) y cierre narrativo (fin del asunto, Dn 7:28). El español ''fin/el fin/hasta el fin de'' capta uniformemente este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120495, 'spa', 'torbellino, tempestad', 'Tormenta violenta y destructiva o tempestad. La palabra aparece exclusivamente en contextos poéticos y proféticos como imagen por excelencia de una fuerza irresistible: arrastra la paja (Job 21:18), acompaña teofanías (Is 29:6; Sal 83:15) y encarna la retribución divina. Su constante emparejamiento con seʿar y rûaḥ en diversos pasajes confirma un único núcleo semántico compacto: violencia atmosférica repentina y abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120506, 'spa', 'apartarse, desviarse (Qal)', 'Qal: apartarse físicamente de un sendero o camino, desviarse para visitar. Paradigmático en Moisés apartándose a ver la zarza (Éx 3:4) e Israel desviándose del camino (Éx 32:8; Dt 9:12). También cubre escenas de hospitalidad donde un viajero ''se desvía'' hacia la casa de alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120507, 'spa', 'quitar, remover (Hifil)', 'Causativo hifil: quitar o remover un objeto, persona o estructura de su lugar. Es la acepción más frecuente (106 veces), abarcando desde Noé quitando la cubierta del arca (Gn 8:13) hasta la retirada de plagas (Éx 8:8) y el desmantelamiento sistemático de instalaciones idolátricas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120509, 'spa', 'marcharse, partir (Qal)', 'Qal: partir de un lugar o persona, irse o alejarse. Comprende la profecía de Jacob de que el cetro no se apartará de Judá (Gn 49:10), las plagas que se retiran de Egipto (Éx 8:11, 29) y la lepra que se va del afligido (Lv 13:58; Nm 12:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120513, 'spa', 'desviarse moralmente (Qal)', 'Qal: apartarse moralmente de los mandamientos de Dios, o del mal, desviación espiritual. Las formas participiales describen carácter: Job ''apartándose del mal'' (Job 1:1) y el persistente estribillo deuteronomista de que los lugares altos ''no fueron quitados'' (1 R 15:14; 22:43; 2 Cr 15:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120520, 'spa', 'eliminar, purgar (Hifil)', 'Hifil: quitar en sentido moral o ritual, eliminar ídolos, el mal o vestiduras. Central en la renovación del pacto: Jacob ordena ''quitad los dioses ajenos'' (Gn 35:2), Tamar se quita sus vestidos de viuda (Gn 38:14, 19) y los pasajes de reforma deuteronomista (Dt 7:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120557, 'spa', 'ser quitado (Hofal)', 'Hofal pasivo: ser quitado por un agente externo. Poco frecuente (4 veces), aparece en la ley sacrificial donde la grasa ''es quitada'' (Lv 4:31, 35), el oráculo de Isaías sobre Damasco que ''será quitada de ser ciudad'' (Is 17:1) y la remoción escatológica del sacrificio diario en Daniel (Dn 12:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120600, 'spa', 'extraviar, hacer desviar', 'Uso poco frecuente en Lm 3:11 donde el sentido parece ser ''extraviar'' o ''hacer desviar del camino''. Implica una desviación causativa con connotación siniestra de ser apartado del rumbo por una fuerza externa, distinta de la simple remoción hifil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120608, 'spa', 'rebelde, desviado (nominal)', 'Nominal o adjetival: un apartado, un rebelde, un desviado; el participio sustantivado que describe a una persona que se ha desviado. Jeremías llama a ciertos personajes סָרֵי ''rebeldes'' (Jer 6:28), confirmándolo como designación de carácter más que como acción. También en 1 S 21:7 e Is 49:21.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120703, 'spa', 'Incitar, instigar a actuar', 'Incitar, instigar a actuar: incitar o instigar a alguien a tomar una acción específica, el sentido central y más frecuente. El instigador ejerce presión o persuasión que mueve a otra persona a actuar, a veces de forma inocua, como cuando Acsa incita a Caleb a concederle tierras (Jos 15:18; Jue 1:14), pero más a menudo con tintes siniestros. David sospecha que alguien ''incitó'' a Saúl contra él (1 S 26:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120705, 'spa', 'Desviar, apartar', 'Desviar, apartar: apartar o desviar a alguien de su rumbo. Una única aparición en 2 Crónicas 18:31, donde Dios ''desvió'' a los capitanes sirios de perseguir a Josafat. El énfasis está en el cambio de dirección más que en la corrupción moral, constituyendo un sentido cinético distinto dentro del rango semántico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120707, 'spa', 'Atraer, sacar', 'Atraer, sacar: atraer o sacar de una situación. Una única aparición en Job 36:16, donde Elihú le dice a Job que Dios ''te atrajo fuera de la angustia.'' El contexto de extracción de aprietos sugiere una atracción benevolente, el único uso inequívocamente positivo de esta raíz en la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120710, 'spa', 'Seducir, tentar', 'Seducir, tentar: seducir o tentar hacia el pecado o la idolatría, donde el énfasis pasa de la simple instigación a la atracción moralmente peligrosa. Deuteronomio 13:6 advierte contra el falso profeta que te ''seduce'' a adorar otros dioses; los oficiales de Ezequías advierten a Judá que Senaquerib los está ''seduciendo'' con falsas promesas (2 Cr 32:11, 15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120719, 'spa', 'Extraviar, engañar', 'Extraviar, engañar: extraviar o desorientar mediante consejo engañoso. Una única aparición en Jeremías 38:22, donde las mujeres de la corte increpan a Sedequías: ''Tus amigos de confianza te han extraviado.'' El contexto profético de traición por falsos consejeros le da a este sentido un matiz político: no mera tentación, sino guía calculada y traicionera que conduce a la ruina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120721, 'spa', 'arrastrar por la fuerza', 'Arrastrar o llevar a rastras con violencia, humillación o compulsión bruta. Husai imagina arrastrar toda una ciudad hasta un valle con sogas (2 S 17:13); Jeremías describe cadáveres arrastrados ignominiosamente (Jer 15:3; 22:19) y cautivos llevados como ovejas por un depredador (Jer 49:20 = 50:45). El español ''arrastrar'' capta fielmente la fuerza física implícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120722, 'spa', 'Harapos y trapos', 'Ambas apariciones (Jeremías 38:11-12) sirven al único propósito narrativo del rescate de Jeremías de la cisterna. Los harapos provienen del depósito de objetos gastados del palacio: incluso los desechos reales resultan útiles para un acto de misericordia. El emparejamiento ''harapos y ropas viejas'' enfatiza tela completamente deteriorada, lo bastante suave para no herir y lo bastante desechable para sacrificarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120723, 'spa', 'Raspar completamente', 'Se encuentra en Ezequiel 26:4, donde Dios declara que raspará el polvo de Tiro al juzgarla. La forma intensiva Piel subraya un raspado exhaustivo y completo. El término evoca la eliminación total de todo material superficial, dejando la roca desnuda. La profecía visualiza a Tiro reducida a peña pelada, despojada de toda huella de su antigua gloria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120724, 'spa', 'Desecho despreciable', 'Aparece en Lamentaciones 3:45, donde la comunidad sufriente lamenta haber sido convertida en «desecho y desprecio» entre las naciones. El emparejamiento con «desprecio» (מָאוֹס) intensifica la degradación. El término expresa no solo derrota sino humillación profunda: ser tratado como el residuo de la historia, indigno siquiera de consideración, material raspado y arrojado lejos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120726, 'spa', 'Mercader, comerciante (sustantivo)', 'Mercader, comerciante (sustantivo): participio Qal usado como sustantivo que significa mercader o comerciante, una persona que viaja comprando y vendiendo mercancías. Es con mucho el uso más frecuente, abarcando negociaciones patriarcales (Gn 23:16), el comercio internacional de Salomón (1 R 10:28; 2 Cr 1:16) y la descripción profética de los socios comerciales de Tiro (Is 23:2; Ez 27:12-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120731, 'spa', 'Comerciar, negociar', 'Comerciar, negociar: formas finitas del Qal (imperfecto, imperativo) que significan dedicarse al comercio o hacer negocios en un lugar. En Génesis 34:10 y 34:21 se invita a los hijos de Jacob a establecerse, comerciar y adquirir propiedades en la tierra; 42:34 repite el permiso de ''comerciar en la tierra.'' La fuerza verbal es de participación comercial activa, no una etiqueta personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120735, 'spa', 'Palpitar, latir (Piel)', 'Palpitar, latir (Piel): sentido semánticamente distinto del Piel que significa palpitar o latir, referido al corazón. Salmo 38:10 dice ''mi corazón palpita'' (סְחַרְחַר). Este tronco intensivo probablemente extiende la idea raíz de dar vueltas en círculos al latido acelerado del corazón. Constituye un uso único en las Escrituras y la mayoría de traducciones lo tratan por separado de los sentidos comerciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120738, 'spa', 'Andar, recorrer', 'Andar, recorrer: significado base del Qal de ir de un lado a otro o recorrer sin connotación comercial específica. Jeremías 14:18 describe al profeta y al sacerdote andando (סָחֲרוּ) por una tierra que no conocen. Se preserva la semántica ambulatoria original del verbo antes de su especialización comercial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120743, 'spa', 'Ganancia comercial', 'Designa la ganancia comercial, el beneficio del intercambio o los réditos mercantiles. Proverbios 3:14 ensalza la ganancia de la sabiduría como superior a la de la plata, mientras que 31:18 describe a la mujer virtuosa que percibe que «su ganancia es buena». Isaías 23:3 y 18 se refieren al comercio de Tiro y los réditos que produce, los cuales serán consagrados al Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120744, 'spa', 'Ganancia comercial', 'Proverbios emplea un doble uso (3:14) creando paralelismo: la ganancia de la sabiduría supera la de la plata. Isaías se centra en el imperio mercantil de Tiro: el «mercado de Sijor» (23:3) que produce mercancía, la cual finalmente servirá a propósitos sagrados (23:18). La mercancía etíope (45:14) representa tributo fluyendo hacia el Israel restaurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120745, 'spa', 'Mercancía comercial', 'Se encuentra en Ezequiel 27:15 dentro del extenso oráculo comercial contra Tiro: «la mercancía de Dedán» y frases similares. El término forma parte del inventario exhaustivo que Ezequiel hace de los socios comerciales de Tiro y sus productos, mostrando cómo la identidad de la ciudad era inseparable de su papel como centro de intercambio internacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120746, 'spa', 'Escudo defensivo', 'Aparece en el Salmo 91:4, donde la fidelidad de Dios se describe como «escudo y rodela», términos defensivos emparejados que conforman una protección total. La metáfora transforma la fidelidad divina en protección militar tangible, haciendo que el cuidado de Dios resulte tan real y concreto como una armadura de bronce o cuero en medio de la batalla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120747, 'spa', 'Piedra ornamental oscura', 'Aparece en Ester 1:6 describiendo las piedras del pavimento del palacio. El término se encuentra junto al mármol en un catálogo de materiales lujosos. El paralelo asirio indica una piedra preciosa usada en arquitectura de alto estatus. La palabra contribuye al retrato que Ester hace del esplendor imperial persa, estableciendo el escenario para los dramáticos acontecimientos que siguen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120748, 'spa', 'Escoria metálica', 'El residuo impuro o la escoria que queda cuando el metal, especialmente la plata, se refina por fuego. Las nueve apariciones conservan este significado metalúrgico central, aunque la mayoría se emplean figuradamente. En Proverbios 25:4 la escoria se separa literalmente de la plata, mientras que en Isaías 1:22, 25 y Ezequiel 22:18-19 la escoria se convierte en una imagen devastadora del pueblo descarriado de Dios, reunido en un horno de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120755, 'spa', 'Nombre de mes', 'Nombre de mes en Ester 8:9, identificado como «el tercer mes» y designado con su nombre babilónico Siván. El texto lo glosa cuidadosamente («que es el mes de Siván»), lo que indica que el nombre aún no estaba plenamente naturalizado en el uso judío. El cognado palmireno confirma el uso extendido de este sistema calendárico babilónico en todo el antiguo Cercano Oriente. El mes marca el momento en que salieron los decretos de Mardoqueo, permitiendo a los judíos defenderse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120756, 'spa', 'El nombre propio masculino Sihón, que designa al rey amorreo de Hesbón cuya derr', 'El nombre propio masculino Sihón, que designa al rey amorreo de Hesbón cuya derrota por Israel en Transjordania (Nm 21:21-32) se convirtió en un evento fundacional en la narrativa de la conquista. Las 37 ocurrencias se refieren a esta única figura. El nombre aparece en tres contextos literarios: (a) el relato original de la batalla en Números y Deuteronomio, (b) retrospectivas históricas que citan a Sihón junto con Og como par formulaico de reyes derrotados (Sal 135:11; 136:19), y (c) invocaciones litúrgicas de la fidelidad divina (Neh 9:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120761, 'spa', 'Desierto de Sin', 'Designación geográfica de una región desértica en la ruta del Éxodo. El Desierto de Sin (מִדְבַּר־סִין) aparece en Éxodo 16:1 (el relato del maná), Éxodo 17:1 (partida hacia Refidim) y Números 33:11-12 (el itinerario por el desierto). Las traducciones en diversos idiomas mantienen el nombre propio «Sin» de manera uniforme, y el griego lo transcribe como Σειν o similar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120763, 'spa', 'El nombre propio del monte y la región desértica del pacto mosaico', 'El nombre propio del monte y la región desértica del pacto mosaico. Concentrado en Éxodo, Levítico y Números (fuente P), marca el lugar de la entrega de la ley (Éx 19:11-20; 31:18), las instrucciones del censo (Nm 1:1) y los campamentos en el desierto (Nm 33:15-16). El nombre alterno Horeb en las fuentes E y D designa el mismo sitio. Las 35 ocurrencias apuntan a la misma geografía sagrada: el lugar donde YHWH descendió en fuego y humo, donde Moisés recibió las tablas del pacto y donde Israel fue constituido como nación santa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120765, 'spa', 'Tierra lejana', 'Término geográfico o étnico en Isaías 49:12, que señala una tierra distante de la cual retornarán los exiliados. La identificación tradicional con China es dudosa. Muchos eruditos enmiendan el texto a «sienitas» (habitantes de Asuán en el sur de Egipto), ofreciendo un equilibrio de direcciones: norte, occidente y sur. El término funciona para extender la reunión de Israel por parte de Dios hasta las regiones más remotas conocidas, mostrando que nadie queda fuera del alcance de la restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120766, 'spa', 'Sísara (nombre propio)', 'Sísara (nombre propio): nombre personal de dos figuras distintas. Principalmente el general cananeo al servicio del rey Jabín, derrotado por Débora y Barac junto al arroyo Cisón (Jue 4:2-22; 5:20-30), muerto por Jael con una estaca de tienda y recordado en la tradición posterior (1 S 12:9; Sal 83:10). Secundariamente, antepasado de una familia de sirvientes del templo que regresaron del exilio (Esd 2:53; Neh 7:55). El nombre puede ser de origen hitita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120772, 'spa', 'Olla o caldero para hervir alimentos o líquidos', 'Olla o caldero para hervir alimentos o líquidos. Es el sentido dominante en 27 apariciones. Las ollas de carne de Egipto (Éx 16:3), la olla de guiso de Eliseo (2 R 4:38-41), las ollas del templo (1 R 7:45; Éx 27:3; 38:3) y la metáfora de Ezequiel del caldero de asedio para Jerusalén (Ez 11:3; 24:3, 6) se refieren todas a recipientes de cocina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120780, 'spa', 'Palangana o lebrillo, un recipiente ancho para lavar, no para cocinar', 'Palangana o lebrillo, un recipiente ancho para lavar, no para cocinar. Limitado a dos pasajes poéticos donde Dios declara ''Moab es mi palangana'' (Sal 60:8; 108:9), una imagen de sometimiento que reduce a una nación a un recipiente servil para lavarse los pies.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120786, 'spa', 'espino, zarza', 'Plantas espinosas que simbolizan desolación, obstrucción o futilidad. Los espinos cubren los palacios de Edom como señal de juicio divino (Is 34:13), Dios cerca con espinos el camino de la esposa infiel (Os 2:8) y el crepitar de espinos bajo la olla ilustra la risa vana del necio (Ecl 7:6). Nahúm 1:10 alude probablemente al enredo en la maraña de espinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120787, 'spa', 'Multitud de peregrinos', 'Aparece en el Salmo 42:4 (numeración de versículos en español), donde el salmista recuerda caminar «con la multitud» hacia la casa de Dios durante las fiestas. La palabra es textualmente incierta, pero se entiende mejor como una masa densa de peregrinos, lo que hace aún más conmovedor el exilio presente del salmista. El contraste entre el recuerdo gozoso y la soledad actual constituye el núcleo emocional del salmo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120788, 'spa', 'Guarida o matorral', 'Designa un escondrijo, guarida o matorral denso, generalmente asociado con leones o imágenes de depredadores. El Salmo 10:9 y Jeremías 25:38 lo usan para el escondite de un león, describiendo metafóricamente la maldad o el juicio divino. El Salmo 27:5 y 76:3 podrían referirse al refugio o morada de Dios, aunque existen cuestiones textuales con las variantes ketiv y qeré.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120789, 'spa', 'Cuando va precedido del artículo (''las Cabañas''), el vocablo funciona como nombr', 'Cuando va precedido del artículo (''las Cabañas''), el vocablo funciona como nombre propio de la fiesta de peregrinación otoñal: Sukkot o Tabernáculos. Levítico 23:34 y Deuteronomio 16:13 fundamentan este sentido litúrgico. Las traducciones francesa y alemana a veces conservan el préstamo hebreo, reflejando el estatus del festival como nombre propio reconocido en todas las tradiciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120790, 'spa', 'Sentido físico primario', 'Sentido físico primario: un refugio rústico y temporal hecho de ramas y follaje entrelazados. Génesis 33:17 muestra a Jacob construyendo cabañas para su ganado en el lugar que llamó Sukkot, mientras que Levítico 23:42 prescribe habitar en tales refugios durante la fiesta. Las traducciones multilingües (español ''cabañas'', alemán ''Laubhütten'', inglés ''booth'') captan la cualidad rústica e impermanente de la estructura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120796, 'spa', 'El sentido más concreto y natural del vocablo', 'El sentido más concreto y natural del vocablo: un matorral denso de vegetación que sirve de escondite para animales. Job 38:40 lo emplea para la espesura donde el león se agazapa al acecho. Este sentido preserva la imagen raíz de ramas entrelazadas sin construcción humana alguna, vinculándose directamente con el núcleo etimológico de la palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120798, 'spa', 'Extensión metafórica que representa la presencia de Dios como un dosel o pabelló', 'Extensión metafórica que representa la presencia de Dios como un dosel o pabellón protector. En Salmo 18:11 (paralelo en 2 Samuel 22:12), el Señor se envuelve en aguas oscuras y nubes densas como su סֻכָּה. Job 36:29 usa la misma imagen para el despliegue del manto tormentoso de Dios. El español ''su pabellón'' y el inglés ''his pavilion'' destacan el matiz regio y protector.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120810, 'spa', 'Deidad asiria', 'Nombre divino en Amós 5:26, identificado con el asirio Sakkut, epíteto de Adar-Ninip/Saturno. El texto hebreo pudo haber sido vocalizado para sugerir «cabaña» (evitando el nombre de la deidad pagana), pero el original se refiere a un dios astral mesopotámico. El pasaje acusa a Israel de adoptar los cultos de sus conquistadores, integrando divinidades extranjeras en su propia adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120811, 'spa', 'Sucot (topónimo)', 'Sucot (topónimo): nombre de lugar que significa ''cabañas,'' referido principalmente a una ciudad transjordana en el valle del Jordán donde Jacob erigió refugios para sus rebaños (Gn 33:17) y que aparece en la campaña de Gedeón contra Madián (Jue 8:5-16), la fundición de bronce de Salomón (1 R 7:46) y la repartición sálmica de la tierra (Sal 60:6; 108:7). Una segunda Sucot es el punto de partida inicial del éxodo desde Egipto (Ex 12:37; 13:20; Nm 33:5-6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120819, 'spa', 'Pueblo africano', 'Designación étnica y militar en 2 Crónicas 12:3, que identifica a un grupo dentro de la fuerza invasora de Sisac. La Septuaginta lee «trogloditas», sugiriendo pueblos moradores de cuevas, posiblemente de regiones cercanas a Etiopía o Libia. El término sitúa a los suquienos entre libios y cusitas geográficamente, como parte de la coalición que amenazó la Jerusalén de Roboam, evidenciando el alcance multinacional de los ejércitos egipcios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120821, 'spa', 'Cubrir, proteger, resguardar', 'Cubrir, proteger, resguardar: cubrir, proteger o brindar amparo. Se dice que los querubines cubren el propiciatorio con las alas extendidas (Ex 25:20; 37:9), Moisés cubre el arca con una cortina (Ex 40:3, 21) y Dios cubre la cabeza de su siervo en la batalla (Sal 140:7). Lamentaciones usa el mismo verbo para describir a Dios cubriéndose con una nube para que la oración no pueda atravesarla (Lm 3:44).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120830, 'spa', 'Incitar, provocar', 'Incitar, provocar: incitar, agitar o enfrentar, un significado semánticamente no relacionado que parece provenir de una raíz homógrafa distinta (frecuentemente clasificada como סכך II en forma Pilpel o reduplicada). En Isaías 19:2 Dios declara ''Enfrentaré a egipcios contra egipcios,'' e Isaías 9:11 lo usa referido al SEÑOR incitando adversarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120836, 'spa', 'Tejer en el vientre', 'Aparece en Salmo 139:13 donde Dios «me tejió» en el vientre. El verbo en Qal con sufijo de primera persona enfatiza la atención divina personal. El español «tejiste» conserva la imagen textil. El paralelismo con Job 10:11, que usa una raíz similar, confirma el sentido de tejer o entretejer, permitiendo a Moisés un encuentro mediado con la gloria de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120837, 'spa', 'Escudo de asedio', 'Término militar en Nahúm 2:5 que describe equipo de asedio: «la cubierta está preparada». La Septuaginta traduce «sus defensas», reconociendo la función protectora. Se trataba esencialmente de un escudo móvil o mantelete que protegía a los atacantes mientras avanzaban contra las fortificaciones. La ironía radica en que Nínive, que tanto había asediado a otros, ahora sufría el mismo destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120838, 'spa', 'Cobertura divina protectora', 'Aparece en Éxodo 33:22 donde Dios promete «cubrirte con mi mano» mientras su gloria pasa ante Moisés. El Qal perfecto con waw consecutivo indica la acción específica y prometida de Dios. Esta cobertura divina permite a Moisés un encuentro mediado con la gloria de Dios: suficiente para transformarlo, pero sin destruirlo, revelando tanto la gracia como la trascendencia del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120839, 'spa', 'Tejer el cuerpo', 'Aparece en Job 10:11 en forma Piel: «con huesos y tendones me tejiste». El verbo es la raíz con שׁ paralela a la raíz con ס del Salmo 139:13, mostrando cómo el hebreo usaba múltiples raíces para conceptos de tejer y entretejer. La imagen enfatiza la artesanía divina: Dios como artesano que construye con esmero los cuerpos humanos entrelazando sus componentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120840, 'spa', 'Ciudad del desierto', 'Nombre de lugar en Josué 15:61, parte de la asignación del desierto de Judá. La ubicación de la ciudad se ha perdido en la memoria histórica. Las versiones griegas ofrecen variantes como Σοχοχα o Σχαχα, evidenciando variación en la transliteración. El nombre aparece dentro de la distribución territorial sistemática, documentando las reclamaciones israelitas sobre regiones escasamente habitadas del desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120841, 'spa', 'Obrar neciamente', 'Sentido intransitivo de actuar necia o insensatamente, expresado mediante las formas Hifil y Nifal. El sujeto es quien ha cometido una torpeza — autoevaluación que recurre en contextos confesionales. Labán acusa a Jacob (Gn 31:28), Samuel reprende a Saúl (1 S 13:13), Saúl admite su propia necedad ante David (1 S 26:21), y David confiesa tras el censo (2 S 24:10; 1 Cr 21:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120843, 'spa', 'Hacer necio, enloquecer', 'Sentido causativo en Piel de hacer necio a alguien o algo, volver insensato un consejo o convertir la sabiduría en locura. Solo dos pasajes atestiguan este uso transitivo: la oración de David para que YHWH «enloquezca» el consejo de Ahitofel (2 S 15:31) e Isaías 44:25, donde Dios frustra a los adivinos y «hace necio» su conocimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120849, 'spa', 'Necio exaltado', 'Aparece en Eclesiastés 10:6, donde «al necio lo colocan en las alturas» mientras los ricos (presumiblemente sabios) ocupan lugares bajos. El término identifica a quien carece de sabiduría y juicio. Con artículo definido, puede referirse al necio por excelencia o representar a los necios como clase. La frustración de Qohélet se centra en la mala distribución del honor y la dignidad en un mundo desordenado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120850, 'spa', 'Necio, insensato', 'Persona caracterizada por una necedad moral e intelectual — no simplemente ignorante sino tercamente insensata. En Eclesiastés, el סָכָל encarna la frustrante realidad de que las ganancias de la sabiduría pueden pasar a un necio (2:19), que incluso su manera de caminar revela su falta de juicio (10:3), y que el necio multiplica palabras sobre lo que no puede conocer (10:14). Jeremías usa la forma plural para acusar la ceguera espiritual de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120856, 'spa', 'Necedad como objeto de estudio', 'Sustantivo abstracto en Eclesiastés 1:17 (y otros seis versículos), parte del programa de Qohélet de «conocer la sabiduría y conocer la locura y la necedad». Denota el comportamiento y pensamiento insensato. El término representa la anti-sabiduría que la literatura sapiencial critica. Qohélet investiga la necedad no para practicarla, sino para comprender el espectro completo de la experiencia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120857, 'spa', 'Necedad, insensatez', 'La necedad como cualidad abstracta, examinada filosóficamente en Eclesiastés como antítesis de la sabiduría. Qohélet la investiga sistemáticamente: «dio su corazón a conocer la necedad» (Ecl 2:3), la comparó con la sabiduría (2:12-13), y concluyó que sabio y necio comparten el mismo destino mortal. En 7:25 y 10:1,13 describe la degradación moral e intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120861, 'spa', 'Cuidadora, asistente', 'Participio Qal femenino usado como sustantivo: una cuidadora o asistente personal que atiende las necesidades cotidianas de alguien. En 1 Reyes 1:2, 4, se busca a Abisag la sunamita como סֹכֶנֶת para el anciano rey David. El término destaca el carácter nutricio y doméstico de esta función, distinto del sentido administrativo de la forma masculina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120862, 'spa', 'Ser provechoso, ser útil', 'Ser provechoso, útil o beneficioso para alguien, usado exclusivamente en los debates sapienciales de Job (Job 15:3; 22:2; 34:9; 35:3). La pregunta «¿Puede el hombre ser provechoso a Dios?» cuestiona la autoimportancia humana ante el Todopoderoso. La metáfora de beneficio económico subyace en este sentido, tratando la conducta moral como mercancía cuyo valor se sopesa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120864, 'spa', 'Familiarizarse, acostumbrarse', 'Forma Hifil que denota familiaridad, conocimiento íntimo o costumbre. En Job 22:21, «reconcíliate» (הַסְכֶּן־נָא) literalmente significa «hazte familiar con Él», urgiendo a una reconciliación íntima con Dios. La burra de Balaam apela a este mismo sentido: «¿Acaso acostumbré hacerte esto?» (Nm 22:30). El Salmo 139:3 lo usa para el conocimiento íntimo que Dios tiene de todos los caminos humanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120867, 'spa', 'Mayordomo, administrador', 'Participio Qal masculino con artículo, funcionando como título: el mayordomo o administrador principal de una casa real. Isaías 22:15 identifica a Sebna como «el mayordomo» (הַסֹּכֵן), un alto funcionario a quien el profeta denuncia por su vanagloria. El hebreo abarca una gestión doméstica más amplia que la mera tesorería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120870, 'spa', 'Peligro ocupacional', 'Verbo nifal en Eclesiastés 10:9: «el que raja leña se pone en peligro con ella». Es hebreo tardío, emparentado con términos arameos y talmúdicos para el peligro. La observación encaja en el patrón de Qohélet de señalar la imprevisibilidad de la vida: incluso tareas sencillas como partir leña entrañan riesgo de daño. El contexto subraya la fragilidad inherente a toda actividad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120871, 'spa', 'Pobre oferente de ídolos', 'Participio pual en Isaías 40:20, tradicionalmente traducido como «el que es demasiado pobre para ofrenda». La palabra y su contexto son textualmente inciertos; muchos eruditos proponen enmiendas. El pasaje satiriza la construcción de ídolos, contrastando imágenes de madera cuidadosamente conservadas con la incomparable grandeza de Dios. La lectura tradicional preserva el sentido de pobreza extrema vinculada a la devoción idolátrica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120872, 'spa', 'Cerrar o confinar', 'Génesis usa el Nifal pasivo para la cesación del diluvio: las fuentes de juicio divino sobrenaturalmente selladas. El Salmo emplea la misma forma para bocas acalladas en la muerte. La forma intensiva Piel en Isaías describe a Dios encerrando a Egipto forzosamente en servidumbre, como agua represada. El verbo abarca desde el bloqueo físico hasta la restricción política.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120873, 'spa', 'Silencio atento', 'Imperativo hifil en Deuteronomio 27:9: «¡Guarda silencio y escucha, oh Israel!». El verbo exige atención activa, no mera ausencia de ruido: Israel debe dejar de hablar para oír la declaración de Moisés. El mandato emparejado «y escucha» muestra que el silencio es intencionado, creando espacio para recibir las palabras del pacto. El contexto solemne subraya la gravedad de la alianza que se proclama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120874, 'spa', 'canasta, recipiente tejido', 'Canasta plana o abierta, tejida, usada para transportar pan, tortas y productos horneados. Sus quince apariciones se agrupan en dos ámbitos narrativos: el sueño del panadero en Génesis 40, donde tres canastas sobre la cabeza presagian la ejecución, y los textos rituales del Pentateuco que prescriben panes sin levadura para la consagración y las ofrendas del nazireato (Éx 29; Lv 8; Nm 6). La asociación constante con alimentos horneados la distingue de otros términos hebreos para recipientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120886, 'spa', 'Estimar, valorar', 'Participio pual en Lamentaciones 4:2: «los preciosos hijos de Sion, pesados contra el oro fino». La imagen proviene de la práctica comercial de pesar oro para determinar su valor. Esas personas, antes estimadas como tesoro invaluable, ahora son tratadas como vasijas de barro desechables, subrayando la devastadora inversión que trajo el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120887, 'spa', 'Topónimo incierto', 'Nombre de lugar (posible) en 2 Reyes 12:20, parte de la descripción del sitio donde fue asesinado Joás. El texto lee «Bet-milo, que desciende a Sila», pero la frase desafía una interpretación clara. Los eruditos han propuesto leer «calzada» o enmendar de otras formas, lo que evidencia la incertidumbre textual. El nombre sirve para ubicar un regicidio cuya localización exacta se ha perdido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120888, 'spa', 'Saltar, exaltarse', 'Imperfecto piel en Job 6:10, un hápax legómenon: «saltaría/me exaltaría en mi angustia». El hebreo misnaico sugiere «retroceder» o «sobresaltarse». La oscuridad del término refleja la dificultad del versículo: Job describe una respuesta emocional hipotética ante la certeza sobre su sufrimiento. La ambigüedad del verbo entre gozo y sobresalto enriquece la tensión teológica del pasaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120892, 'spa', 'Anotación litúrgica o musical de significado incierto, que aparece 71 veces en l', 'Anotación litúrgica o musical de significado incierto, que aparece 71 veces en los Salmos y 3 en Habacuc (Sal 3:2, 4, 8; Hab 3:3, 9). Posiblemente derivada de סָלַל (''elevar''), podría señalar una pausa, un cambio melódico o una indicación doxológica. La Septuaginta la traduce como diapsalma (''interludio''). Casi todos los idiomas modernos simplemente la transliteran: Selah, Sela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120893, 'spa', 'Nombre benjaminita', 'Nombre propio en Nehemías 11:8, que identifica a un colono benjaminita en la Jerusalén postexílica. El texto lee «Gabai, Salai» (posiblemente dos nombres o un compuesto), pero la comparación con 1 Crónicas 9:8 muestra diferencias textuales significativas que sugieren corrupción. El nombre podría derivar de términos que significan «recaudador» y documenta la participación familiar en la repoblación de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120894, 'spa', 'Sacerdote postexílico', 'Nombre propio de un sacerdote que sirvió durante la administración de Zorobabel tras el regreso del exilio (Neh 12:7). La identidad parece conectada con Salai en el versículo 20 del mismo capítulo, mostrando la variación típica de los nombres hebreos. La evidencia interlingüística es mínima dado que se trata de una única ocurrencia de este nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120895, 'spa', 'Nombre personal', 'Nombre propio de un líder tribal de Simeón, padre de Zimri, quien fue ejecutado por Finees en Baal-peor (Nm 25:14). Los testimonios de la Septuaginta muestran diversos intentos de transliterar este nombre hebreo al griego. Las traducciones al español, francés y alemán lo transcriben uniformemente como ''Salú''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120897, 'spa', 'Frase preposicional sacerdotal', 'Frase preposicional ''a Salai'' que designa a una figura sacerdotal en los registros genealógicos de Nehemías (Neh 12:20). Aparece en una lista que coordina asignaciones o relaciones sacerdotales. La preposición לְ indica dirección, posesión o asociación, señalando aquí al destinatario en un contexto administrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120899, 'spa', 'Ser perdonado (Nifal pasivo) — recibir el perdón divino', 'Ser perdonado (Nifal pasivo) — recibir el perdón divino. Concentrado en las regulaciones sacrificiales levíticas (Lv 4:20-5:18), aparece en la fórmula recurrente וְנִסְלַח לוֹ (''y le será perdonado''). Presupone un ritual de expiación apropiado y mediación sacerdotal. La construcción pasiva mantiene a Dios como agente implícito del perdón aun sin nombrarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120900, 'spa', 'Perdonar, indultar (Qal activo) — Dios perdona, remite o absuelve el pecado y la', 'Perdonar, indultar (Qal activo) — Dios perdona, remite o absuelve el pecado y la iniquidad. Siempre con Dios como sujeto, ya sea en discurso directo (''He perdonado'', Nm 14:20), en súplica (''Perdona, oh Señor'', Dn 9:19) o en promesa (''Perdonaré su iniquidad'', Jer 31:34). La evidencia multilingüe confirma el carácter exclusivamente divino de este acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120908, 'spa', 'Sufijo preposicional (''a ti'') — una sola ocurrencia en Jeremías 5', 'Sufijo preposicional (''a ti'') — una sola ocurrencia en Jeremías 5:7 donde la forma textual parece ser una frase preposicional (lamed + sufijo 2fs) en lugar del verbo סָלַח. Probablemente se trata de un artefacto de análisis morfológico; la lectura Qere apoya una forma verbal. No representa un sentido semántico genuino de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120917, 'spa', 'Atributo divino de perdón', 'Atributo divino de estar dispuesto a perdonar, aplicado al Señor en el Salmo 86:5. El término expresa no solo capacidad sino disposición: Dios se caracteriza por una actitud misericordiosa ante el fracaso humano. Se usa junto con ''bueno'' (טוֹב) para describir la naturaleza esencial del Señor. La forma gramatical sugiere una cualidad estable, no una acción momentánea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120918, 'spa', 'Perdón divino', 'Las tres apariciones confiesan el carácter perdonador de Dios en contextos de pecado nacional. Nehemías rememora la rebelión en el desierto contrastándola con la paciencia divina. El salmista vincula perdón con temor reverente, inspirando asombro, no libertinaje. Daniel reconoce que, pese a la infidelidad de Judá, Dios se caracteriza por sus perdones. Los plurales enfatizan magnitud inagotable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120919, 'spa', 'Ciudad de Salca', 'Nombre propio geográfico que designa una ciudad en la frontera oriental de Basán. Salca aparece en las listas de conquista y límites territoriales (Deuteronomio 3:10, Josué 12:5, 13:11) y en las asignaciones tribales (1 Crónicas 5:11). Las transliteraciones son uniformes: Salca/Salecah/Salkhad. Las versiones griegas lo transcriben como Σελχα o Ελχα. Su identificación con la moderna Salkhad en la meseta del Haurán está bien establecida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120920, 'spa', 'Construir, preparar camino', 'Levantar o construir una calzada despejando obstáculos y alzando un terraplén. Es el sentido central del Qal, que ordena preparar el camino para la venida divina (Is 57:14; 62:10). El participio pasivo en Proverbios 15:19 describe un sendero bien «preparado», contrastado con el camino espinoso del perezoso. Refleja el trabajo físico de construcción de caminos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120922, 'spa', 'Apilar, amontonar', 'Apilar o amontonar material, una aplicación especializada del sentido de «levantar» de la raíz, orientada al asedio o la destrucción. En Jeremías 50:26, el imperativo ordena apilar las provisiones de Babilonia para su destrucción. Este uso estrecho y militarista se distingue tanto de la construcción de caminos como de la alabanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120926, 'spa', 'Ensalzar, exaltar', 'Elevar en alabanza o exaltar, extendiendo el «levantar» físico al ámbito del honor y la adoración. El Salmo 68:4 exhorta a «entonad cánticos al que cabalga sobre las nubes», y Proverbios 4:8 manda «ensálzala» refiriéndose a la Sabiduría. En Éxodo 9:17, la autoexaltación del Faraón (Hitpael) invierte el sentido positivo en arrogancia desafiante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120929, 'spa', 'Terraplén de asedio', 'Rampa o terraplén de tierra construido contra el exterior de la muralla de una ciudad fortificada durante operaciones de asedio, permitiendo a los atacantes llevar arietes y tropas hasta la altura de la muralla. Joab levanta uno contra Abel Bet-Maacá (2 Sam 20:15), Senaquerib amenaza pero nunca construye uno contra Jerusalén (2 Re 19:32; Is 37:33), y los ingenieros de Nabucodonosor los construyen en Jerusalén (Jer 32:24; 33:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120936, 'spa', 'Escalera celestial', 'Escalera o escalinata en el sueño de Jacob en Betel (Gn 28:12), que sirve como vía para el tránsito angélico entre la tierra y el cielo. Todas las tradiciones de traducción lo vierten uniformemente como ''escalera'', subrayando la estructura de acceso vertical. La visión estableció Betel como lugar de encuentro entre cielo y tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120937, 'spa', 'Ramas o cestos', 'Racimos de ramas o cestos de vendimia en una escena de rebusca en la viña (Jer 6:9). Este sustantivo hebreo aparece solo aquí, lo que dificulta una definición precisa. El español opta por ''cestos'', mientras que las propuestas académicas favorecen ''brotes/ramas'' vinculándolo a la imaginería vitícola. El contexto describe una rebusca exhaustiva como metáfora del juicio divino que agota al pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120938, 'spa', 'Roca, risco (accidente geográfico) — el sentido primario y literal', 'Roca, risco (accidente geográfico) — el sentido primario y literal: una gran formación rocosa, pared de risco o peñasco como elemento geológico. Es el significado predominante en la mayoría de las 43 ocurrencias, abarcando desde la roca de Meribá que Moisés golpeó (Nm 20:8-11) hasta los riscos donde se esconden los fugitivos (1 S 23:25) y donde se labran sepulcros (Is 22:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120939, 'spa', 'Roca (epíteto divino) — un notable uso metafórico donde ''roca'' se convierte en e', 'Roca (epíteto divino) — un notable uso metafórico donde ''roca'' se convierte en epíteto divino que expresa el papel de Dios como fortaleza inexpugnable y refugio personal (6 ocurrencias). Aparece típicamente con sufijos posesivos — ''mi roca'' (סַלְעִי) en 2 S 22:2 y Sal 18:2 — en paralelo con otras imágenes de fortaleza. ''Mi peña'' en español conserva esta expresión devocional íntima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120945, 'spa', 'Rocas, peñascos (terreno plural) — la forma plural referida a riscos rocosos com', 'Rocas, peñascos (terreno plural) — la forma plural referida a riscos rocosos como accidentes del terreno agreste, frecuentemente como lugares de ocultamiento o refugios inaccesibles (9 ocurrencias). En Is 2:21 la gente huye ''a las peñas'' (בַּסְּלָעִים) para refugiarse del juicio divino, mientras que Sal 104:18 señala los riscos como hogar de los damanes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120958, 'spa', 'Sela (nombre propio) — el nombre propio Sela, que identifica la ciudad-fortaleza', 'Sela (nombre propio) — el nombre propio Sela, que identifica la ciudad-fortaleza edomita conocida después como Petra (1 ocurrencia, Jue 1:36). El nombre deriva transparentemente del sustantivo común: una ciudad tallada en y definida por sus imponentes riscos de roca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120962, 'spa', 'Fortaleza edomita', 'Las tres referencias abarcan conquista histórica (2 Reyes 14:7), frontera tribal (Jueces 1:36) y geografía profética (Isaías 16:1). La victoria de Amasías y el cambio de nombre demuestran la expansión judía en territorio edomita. La referencia de Isaías sugiere a Sela como punto diplomático y comercial conocido, desde el cual podía enviarse tributo a través del desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120964, 'spa', 'Langosta comestible', 'Especie de langosta kosher mencionada en el código dietético levítico (Lv 11:22), uno de cuatro insectos voladores permitidos. Su etimología sugiere conexión con ''tragar/consumir'', reflejando los hábitos alimenticios destructivos del insecto. Las traducciones destacan ''langosta calva'' como rasgo físico distintivo, posiblemente relacionado con las vainas alares o la forma de la cabeza que la diferenciaba de otras especies.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120965, 'spa', 'Torcer, pervertir, derribar', 'Torcer, pervertir o trastornar en sentido judicial o moral. El uso legal aparece en Éx 23:8 y Dt 16:19, donde el soborno «pervierte» la causa del justo. El uso sapiencial en Proverbios amplía el alcance: Pr 19:3 dice que la necedad propia «tuerce» el camino; Pr 13:6 declara que la maldad «derriba» al pecador; y Pr 22:12 afirma que Dios «trastorna» las palabras del traidor. Job 12:19 lo extiende al plano cósmico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120972, 'spa', 'subir, ascender', 'Subir, ascender o surgir, aplicado tanto al movimiento físico como al visionario en contextos arameos. Las bestias ascienden del mar (Dn 7:3), un cuerno surge entre los demás (Dn 7:8, 20), los exiliados suben a Jerusalén (Esd 4:12) y los pensamientos brotan en la mente (Dn 2:29). La forma causativa haf''el significa ''hacer subir'' o ''elevar.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120973, 'spa', 'Harina fina de trigo de calidad superior, utilizada predominantemente en las ofr', 'Harina fina de trigo de calidad superior, utilizada predominantemente en las ofrendas de cereal levíticas (Lv 2:1-7; Nm 28-29) y también en la hospitalidad doméstica de élite. Abraham ofreció סֹלֶת a sus visitantes celestiales (Gn 18:6), la casa de Salomón la consumía a diario (1 R 5:2) y Ezequiel 16:13 la enumera entre los alimentos lujosos de Jerusalén. Durante el asedio arameo de Samaria, una sea de flor de harina se vendía a precio de hambruna (2 R 7:1), subrayando su habitual carestía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120981, 'spa', 'Especias, sustancias aromáticas', 'Especias, sustancias aromáticas: sustancias aromáticas fragantes destinadas a propósitos cultuales sagrados, específicamente la preparación del incienso del tabernáculo y el aceite de unción. El término aparece solo en la legislación sacerdotal y Crónicas, siempre en la cadena constructa קְטֹרֶת הַסַּמִּים (''incienso de especias'') o en listas de materiales del tabernáculo (Ex 25:6; 30:34; 2 Cr 2:3; 13:11). Las especias incluían estacte, uña aromática, gálbano e incienso (Ex 30:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120988, 'spa', 'Flor de la vid', 'Los tres usos aparecen en la extensa metáfora vinícola del Cantar de los Cantares sobre el amor y el cortejo. La vid en cierne representa el amor en su etapa más tierna y vulnerable, llena de promesa pero aún inmadura. En 2:13 las «vides en cierne» se equiparan a la «higuera madurando», ambas señales tempranas de fecundidad inminente. Las zorras (2:15) amenazan justamente el momento más frágil de la floración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120989, 'spa', 'Imponer las manos — colocar las manos sobre la cabeza de un animal sacrificial o', 'Imponer las manos — colocar las manos sobre la cabeza de un animal sacrificial o sobre una persona para ordenación, bendición o comisionamiento. El uso más frecuente con 23 ocurrencias, concentrado en Levítico y Números. El oferente ''apoya su mano'' sobre el holocausto (Lv 1:4; 3:2, 8, 13; 4:4), y Moisés ''impone sus manos'' sobre Josué para comisionarlo (Nm 27:18, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120993, 'spa', 'Sostener o sustentar a una persona — típicamente con Dios como sujeto, proporcio', 'Sostener o sustentar a una persona — típicamente con Dios como sujeto, proporcionando fortaleza, sustento o aliento. En Sal 3:5 David declara ''el SEÑOR me sustenta''; en Sal 119:116 el salmista suplica ''Susténtame conforme a tu palabra''; Cnt 2:5 pide ser ''sustentada con tortas de pasas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120994, 'spa', 'El que sostiene — la forma participial que describe a quien sostiene, apoya o su', 'El que sostiene — la forma participial que describe a quien sostiene, apoya o sustenta como agente continuo. Sal 145:14 declara ''El SEÑOR sostiene a todos los que caen''; Sal 37:17 promete que ''el SEÑOR sostiene a los justos''; Is 63:5 pregunta ''¿No hay nadie que sostenga?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (120999, 'spa', 'Apoyarse en o depender de — apoyarse en algo o alguien para soporte físico o fig', 'Apoyarse en o depender de — apoyarse en algo o alguien para soporte físico o figurativo. Sansón ''se apoya'' en las columnas del templo filisteo (Jue 16:29); Ezequías advierte contra ''apoyarse'' en Egipto como una caña quebrada (2 R 18:21; Is 36:6). El paso del sentido activo de ''sostener'' al reflexivo de ''depender'' es claro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121003, 'spa', 'Oprimir o pesar sobre — presionar o caer pesadamente sobre algo, indicando peso ', 'Oprimir o pesar sobre — presionar o caer pesadamente sobre algo, indicando peso físico o presión opresiva. En Sal 88:7 el salmista lamenta ''tu ira pesa sobre mí'', y en Ez 24:2 Nabucodonosor ''ha puesto sitio'' contra Jerusalén. Una inversión oscura de la valencia habitual del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121004, 'spa', 'Firme o establecido — el participio pasivo que describe un estado de firmeza, es', 'Firme o establecido — el participio pasivo que describe un estado de firmeza, estabilidad o constancia. En Is 26:3 una mente ''firme'' (סָמוּךְ) en Dios es guardada en perfecta paz; Sal 111:8 dice que los preceptos de Dios están ''establecidos'' para siempre; Sal 112:8 describe al justo cuyo corazón está ''firme''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121023, 'spa', 'Portero levítico', 'Nombre propio de un portero levítico de la división coraíta (1 Cr 26:7). El nombre teofórico significa ''Yahvé ha sostenido'', reflejando la teología del pacto en las prácticas de nominación. En español se adapta como ''Semaquías'' con la adaptación estándar del elemento yahvista. Su función indica la responsabilidad confiada de custodiar el acceso y la seguridad del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121024, 'spa', 'Ídolo o imagen cúltica', 'Imagen idolátrica o estatua de culto, una representación física erigida para adoración que provoca los celos divinos. Deuteronomio 4:16 prohíbe fabricar tales figuras; Manasés instala una en el Templo (2 Cr 33:7) y después la retira (2 Cr 33:15). Ezequiel 8:3, 5 describe la «סֵמֶל de los celos» junto a la puerta del Templo, un ídolo que desata la indignación de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121025, 'spa', 'Lugar designado', 'Probablemente ''en su lugar/porción designada'', describiendo la siembra organizada de cebada (Is 28:25), aunque la integridad textual es disputada. El participio nifal sugiere algo ''señalado'' o ''designado''. Sin embargo, su ausencia en la Septuaginta y su similitud con la palabra adyacente כֻּסֶּמֶת (espelta) llevan a muchos eruditos a considerarlo una duplicación escribal y no texto original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121027, 'spa', 'Langosta erizada', 'Término descriptivo para un tipo de langosta caracterizada por su apariencia erizada o áspera (Jer 51:27). Los eruditos lo relacionan con las estructuras de vainas alares visibles en la fase de pupa, creando un aspecto espinoso. El adjetivo intensifica la imaginería amenazante de la invasión militar comparada con la devastación causada por langostas. El español ''erizadas'' captura la cualidad punzante del insecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121028, 'spa', 'Familia postexílica', 'Las dos apariciones en listas censales (Esdras 2:35, Nehemías 7:38) registran a uno de los grupos más grandes que retornaron del exilio. La tercera mención (Nehemías 3:3) señala su participación en la reconstrucción de la Puerta del Pescado. La alternancia entre «Senaá» y «Hassenaá» sugiere variantes escribales o la fusión del artículo definido con el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121029, 'spa', 'Sanbalat (nombre propio)', 'Nombre propio que designa al gobernador horonita de Samaria que se opuso persistentemente a la restauración de Jerusalén por Nehemías. Su oposición adopta múltiples formas a lo largo de la narrativa: burla e ira (Neh 2:10, 19; 4:1), conspiración militar con Tobías y Gesem (Neh 4:7; 6:1-2), invitaciones engañosas (Neh 6:5) e infiltración mediante matrimonios mixtos con la familia sacerdotal (Neh 13:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121034, 'spa', 'La zarza', 'Zarza espinosa identificada como el lugar de la aparición de Dios a Moisés en Horeb. Éxodo 3:2-4 emplea la palabra cinco veces en rápida sucesión mientras Moisés observa la zarza ardiendo sin consumirse y escucha la voz de Dios. Deuteronomio 33:16 rememora esta teofanía invocando «el favor del que habitó en la zarza».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121037, 'spa', 'Peñasco geográfico', 'Nombre propio de un risco o peñasco rocoso situado frente a Boses en el paso entre Micmas y Geba (1 S 14:4). El lugar fue central en el ataque de Jonatán contra la guarnición filistea. La etimología posiblemente conecta con ''espinoso'', describiendo el terreno agreste. Las traducciones lo transliteran consistentemente como Sené, conservando el topónimo sin traducirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121039, 'spa', 'Ceguera sobrenatural', 'Las tres apariciones involucran intervención milagrosa contra enemigos del pueblo de Dios. Los hombres de Sodoma quedan ciegos para proteger a los visitantes angélicos de Lot: buscan la puerta a tientas sin hallarla. La ceguera del ejército arameo (2 Reyes 6:18) es explícitamente temporal — Eliseo pide luego que se les restaure la vista — funcionando como confusión estratégica más que castigo permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121040, 'spa', 'Senaquerib (nombre propio)', 'Nombre propio del rey asirio Senaquerib, hijo de Sargón II y padre de Esarhadón, quien reinó entre 705 y 681 a.C. Las trece apariciones bíblicas se refieren a su confrontación militar con Judá bajo el rey Ezequías: su invasión (2 R 18:13; 2 Cr 32:1; Is 36:1), sus mensajes provocadores a Jerusalén (2 R 19:16; 2 Cr 32:9–10), la respuesta profética de Isaías (2 R 19:20; Is 37:21) y su muerte violenta a manos de sus hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121043, 'spa', 'Racimos de palmera', 'Tallos frutales o racimos de la palmera datilera (Cnt 7:8), donde los dátiles cuelgan en manojos. Identificado como préstamo arameo basado en cognados siríacos y asirios. El amante usa la metáfora de trepar; agarrar estas ramas representa la intimidad con la amada. La estructura de crecimiento agrupado de la palmera aporta riqueza a la imagen poética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121044, 'spa', 'Ciudad de Judá', 'Asentamiento en la asignación tribal del sur de Judá (Jos 15:31), probablemente idéntico a Hazar-susa y Hazar-susim en listas paralelas. Su ubicación se sitúa cerca de Gaza, pero el sitio específico es incierto. Las variantes de la Septuaginta reflejan los intentos griegos habituales de transcribir topónimos semíticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121045, 'spa', 'Aleta de pez', 'La aleta de una criatura acuática, que funciona como uno de los dos requisitos (junto con las escamas) para la pureza ritual según las leyes alimentarias. Las cinco apariciones se encuentran en Levítico 11:9-12 y Deuteronomio 14:9-10, donde la presencia conjunta de aletas y escamas determina la comestibilidad. El término conlleva fuerza prescriptiva: no es mera anatomía, sino un criterio legal para la santidad alimentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121046, 'spa', 'Polilla destructora', 'Polilla de la ropa o gusano que devora tejidos, usado metafóricamente para el juicio destructivo (Is 51:8). El insecto consume silenciosa pero inevitablemente las vestiduras de lana, proporcionando una imagen apta de cómo el juicio divino actúa contra los malvados. Cognados en diversas lenguas semíticas confirman la identificación del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121048, 'spa', 'Sostener, sustentar', 'Sentido primario de brindar apoyo, sustento o fortaleza a una persona. Dios sostiene la diestra del salmista (Sal 18:35) y la misericordia mantiene firme el trono de un rey (Pr 20:28). La imagen concreta es la de mantener algo erguido. El cognado arameo sʿaḏ también significa ''apoyar, fortalecer'', confirmando este como el significado central en toda la familia semítica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121050, 'spa', 'Reconfortarse con alimento', 'Uso especializado que significa reconfortarse comiendo, donde sustentar se concreta en el acto de tomar una comida. En 1 Re 13:7 se invita al varón de Dios a ir a casa y ''reconfortarse'' con alimento. Este sentido se volvió predominante en el hebreo rabínico posterior, donde סָעַד es el término estándar para comer o tomar una comida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121059, 'spa', 'Apoyo activo', 'Participio Pael que significa ''apoyar/ayudar'', describiendo la asistencia activa de los profetas en la reconstrucción del templo (Esd 5:2). La forma intensiva indica un apoyo continuo y firme, no una ayuda esporádica. Esta sección aramea de Esdras emplea naturalmente vocabulario arameo para un ministerio profético que combinaba aliento, ayuda práctica y autoridad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121060, 'spa', 'Viento tempestuoso', 'Participio que describe un viento impetuoso o violento (Sal 55:8), usado junto a ''tempestad'' en construcción paralela. El verbo enfatiza el movimiento feroz y rápido de la tormenta más que solo su fuerza. Cognados árabes confirman las asociaciones con movimiento veloz y acción enérgica. El salmista busca liberación tanto de enemigos humanos como de tormentas metafóricas de aflicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121061, 'spa', 'Hendidura, grieta rocosa', 'Fisura o grieta en un acantilado rocoso, usada como lugar de refugio u ocultamiento. Sansón se esconde en la hendidura de la peña de Etam (Jue 15:8, 11), e Isaías describe en dos ocasiones a personas buscando amparo en las grietas de las rocas ante el terror del SEÑOR (Isa 2:21, 57:5). La imagen evoca el agreste terreno de Judea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (121063, 'spa', 'Rama, ramaje arbóreo', 'Rama o ramaje de un árbol, presente únicamente en la poesía profética de Isaías. En Isa 17:6 describe las ramas más altas de un frutal donde quedan unas pocas aceitunas tras la cosecha, metáfora del remanente de Israel. En Isa 27:10 las ramas de una ciudad desolada son quebradas, extendiendo la imagen orgánica al ámbito urbano.');